export function englishLabContentFor(moduleId: string): EnglishLabContent {
  if (!Object.hasOwn(englishLabContent, moduleId)) {
    throw new Error(`Missing English lab overlay for ${moduleId}`);
  }
  return englishLabContent[moduleId as CanonicalModuleId];
}
